using System;
using System.IO;

public static class Utilidades
{
    /// <summary>
    /// Conta el número de palabras en un archivo.
    /// </summary>
    /// <param name="rutaArchivo">La ruta del archivo a leer.</param>
    /// <returns>El número de palabras en el archivo.</returns>
    /// <exception cref="ArgumentException">Si la ruta del archivo es nula o vacía.</exception>
    /// <exception cref="FileNotFoundException">Si el archivo no existe en la ruta especificada.</exception>
    public static int ContarPalabras(string rutaArchivo)
    {
        Validador.ValidarArgumentoNoNulo(rutaArchivo);

        if (!File.Exists(rutaArchivo))
        {
            throw new FileNotFoundException("El archivo no existe en la ruta especificada.", rutaArchivo);
        }

        string contenido = File.ReadAllText(rutaArchivo);
        string[] palabras = contenido.Split(new char[] { ' ', '\t', '\n', '\r', '.', ',', '!', '?' }, StringSplitOptions.RemoveEmptyEntries);
        return palabras.Length;
    }
}

