public class TextProcessor
{
    // Constructor
    public TextProcessor()
    {
    }

    // Función para contar palabras en un texto
    public int CountWords(string text)
    {
        // Casos límite
        if (string.IsNullOrWhiteSpace(text))
        {
            return 0;
        }

        // Algoritmo
        string[] words = text.Split(new char[] { ' ', '.', ',', '!', '?' }, StringSplitOptions.RemoveEmptyEntries);
        return words.Length;
    }

    // Función para contar caracteres en un texto
    public int CountCharacters(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return 0;
        }

        return text.Length;
    }

    // Función para contar frases en un texto
    public int CountSentences(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return 0;
        }

        string[] sentences = text.Split(new char[] { '.', '!', '?' }, StringSplitOptions.RemoveEmptyEntries);
        return sentences.Length;
    }

    // Función para convertir texto a mayúsculas
    public string ToUpperCase(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return text;
        }

        return text.ToUpper();
    }

    // Función para convertir texto a minúsculas
    public string ToLowerCase(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return text;
        }

        return text.ToLower();
    }

    // Función para invertir el orden de las palabras en un texto
    public string ReverseWords(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return text;
        }

        string[] words = text.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
        Array.Reverse(words);
        return string.Join(" ", words);
    }
}

