    os.makedirs(os.path.dirname(os.path.abspath(ruta)), exist_ok=True)
    with open(ruta, 'w', encoding='utf-8') as f:
        json.dump([n.a_dict() if hasattr(n, 'a_dict') else {} for n in neuronas], f)

