    @staticmethod
    def he(shape: Tuple[int, ...], fan_in: int, rng=None) -> np.ndarray:
        r = rng or np.random.default_rng(LUCIA_CONFIG.get('random_seed', 42))
        return (r.normal(0.0, float(np.sqrt(2.0 / max(1, fan_in))), shape)).astype(_dtype())

