def _cargar_submodulos() -> None:
    pares = [('EN1_RN', 'NeuronaEntradaBasica'), ('EN2_RN', 'NeuronaEntradaXavier'), ('EN3_RN', 'NeuronaEntradaLeCun'), ('EN4_RN', 'NeuronaEntradaNormalizada'),
