             ('EN8_RN', 'NeuronaEntradaReLU'), ('EN9_RN', 'NeuronaEntradaTanh'), ('EN10_RN', 'NeuronaEntradaSigmoid')]
    for _mod, _cls in pares:
        try:
            globals()[_cls] = getattr(__import__(f"{__name__}.{_mod}", fromlist=[_cls]), _cls)
        except ImportError:
            pass

_cargar_submodulos()

